body.script:
/* ---------- utilidades ---------- */
function mulberry32(a) {
	return function () {
		a |= 0; a = a + 0x6D2B79F5 | 0;
		let t = Math.imul(a ^ a >>> 15, 1 | a);
		t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
		return ((t ^ t >>> 14) >>> 0) / 4294967296;
	};
}

const BAYER = [[0,8,2,10],[12,4,14,6],[3,11,1,9],[15,7,13,5]].map(r => r.map(v => (v + .5) / 16));

/* ---------- peón ---------- */
(function () {
	const grid = [
		"...XXX...", "..XXXXX..", "..XXXXX..", "...XXX...",
		"..XXXXX..", "...XXX...", "...XXX...", "..XXXXX..",
		".XXXXXXX.", ".XXXXXXX.", "XXXXXXXXX"
	];
	const svg = document.getElementById("pawn");
	grid.forEach((row, y) => [...row].forEach((c, x) => {
		if (c !== "X") return;
		const r = document.createElementNS("http://www.w3.org/2000/svg", "rect");
		r.setAttribute("x", x); r.setAttribute("y", y);
		r.setAttribute("width", 1); r.setAttribute("height", 1);
		svg.appendChild(r);
	}));
})();

/* ---------- escena: cielo, luna, castillo, lava ---------- */
(function () {
	const cv = document.getElementById("scene");
	const W = cv.width, H = cv.height;
	const g = cv.getContext("2d");
	const rnd = mulberry32(7);

	const px = (x, y, c) => {
		x = Math.floor(x); y = Math.floor(y);
		if (x < 0 || y < 0 || x >= W || y >= H) return;
		g.fillStyle = c; g.fillRect(x, y, 1, 1);
	};

	function ellipse(cx, cy, rx, ry, c) {
		for (let y = Math.floor(cy - ry); y <= cy + ry; y++)
			for (let x = Math.floor(cx - rx); x <= cx + rx; x++)
				if (((x - cx) / rx) ** 2 + ((y - cy) / ry) ** 2 < 1) px(x, y, c);
	}

	/* cielo con bandas tramadas */
	const bands = ["#1b060d", "#2b0a12", "#430d17", "#5e121c", "#7a1a22", "#92252a"];
	const skyEnd = 104;
	for (let y = 0; y < skyEnd; y++) {
		const t = y / skyEnd * (bands.length - 1);
		const i = Math.floor(t), f = t - i;
		for (let x = 0; x < W; x++) {
			const c = f > BAYER[y & 3][x & 3] ? bands[Math.min(i + 1, bands.length - 1)] : bands[i];
			px(x, y, c);
		}
	}
	g.fillStyle = bands[5]; g.fillRect(0, skyEnd, W, H - skyEnd);

	/* nubes */
	function cloud(cx, cy, rx, ry, body, rim) {
		for (let y = Math.floor(cy - ry); y <= cy + ry; y++)
			for (let x = Math.floor(cx - rx); x <= cx + rx; x++) {
				const d = ((x - cx) / rx) ** 2 + ((y - cy) / ry) ** 2;
				if (d >= 1) continue;
				const up = ((x - cx) / rx) ** 2 + ((y + 1.5 - cy) / ry) ** 2;
				px(x, y, up >= 1 && y < cy ? rim : body);
			}
	}
	for (let k = 0; k < 9; k++) cloud(rnd() * W, 6 + rnd() * 44, 18 + rnd() * 28, 2 + rnd() * 4, "#2c0a13", "#8a2a2f");
	for (let k = 0; k < 5; k++) cloud(rnd() * 120, 4 + rnd() * 26, 30 + rnd() * 30, 4 + rnd() * 5, "#1a060c", "#5e1a22");

	/* luna */
	const mx = 196, my = 27, mr = 16;
	for (let y = my - mr - 11; y <= my + mr + 11; y++)
		for (let x = mx - mr - 11; x <= mx + mr + 11; x++) {
			const d = Math.hypot(x - mx, y - my);
			if (d > mr + 2 && d < mr + 10 && (1 - (d - mr - 2) / 8) > BAYER[y & 3][x & 3] + .1) px(x, y, "#a82e2e");
		}
	ellipse(mx, my, mr + 2, mr + 2, "#120609");
	for (let y = my - mr; y <= my + mr; y++)
		for (let x = mx - mr; x <= mx + mr; x++) {
			const d = Math.hypot(x - mx, y - my);
			if (d >= mr) continue;
			const s = Math.hypot((x - mx + 5) / mr, (y - my + 5) / mr);
			px(x, y, s < .45 ? "#ff917e" : s < .8 ? "#ee6358" : s < 1.1 ? "#cf4a47" : "#a63a3d");
		}
	[[-6,-5,4],[5,-8,3],[-9,5,3],[6,7,4],[1,1,2],[10,0,2],[-2,10,2]].forEach(([dx, dy, r]) => {
		ellipse(mx + dx, my + dy, r, r, "#b8423f");
		ellipse(mx + dx - 1, my + dy - 1, r - 1.2, r - 1.2, "#c84c47");
	});

	/* colinas */
	function hill(base, terms, fill, rim, extra) {
		for (let x = 0; x < W; x++) {
			let y0 = base;
			terms.forEach(([a, f, p]) => y0 += a * Math.sin(x * f + p));
			if (extra) y0 += extra(x);
			y0 = Math.floor(y0);
			g.fillStyle = fill; g.fillRect(x, y0, 1, H - y0);
			if (rim) px(x, y0, rim);
		}
	}

	hill(78, [[7, .03, 2], [3, .09, .4]], "#58343c", "#7a4a50");
	hill(86, [[6, .045, 0], [3, .11, 1.3], [2, .23, 2]], "#6b4549", "#8f6165");

	/* castillo */
	const castleColor = "#170b13", castleLight = "#2d1824", base = 132;
	const towers = [
		{ x: 184, w: 7, h: 44, s: 22 }, { x: 193, w: 6, h: 60, s: 32 },
		{ x: 202, w: 9, h: 74, s: 38 }, { x: 214, w: 6, h: 54, s: 28 },
		{ x: 223, w: 8, h: 46, s: 22 }, { x: 233, w: 5, h: 34, s: 16 },
		{ x: 240, w: 6, h: 24, s: 12 }
	];
	// bloque principal
	g.fillStyle = castleColor; g.fillRect(186, base - 52, 56, 52);
	for (let x = 186; x < 242; x += 4) { g.fillRect(x, base - 55, 2, 3); }
	towers.forEach(t => {
		const top = base - t.h;
		g.fillStyle = castleColor; g.fillRect(t.x, top, t.w, t.h);
		g.fillStyle = castleLight; g.fillRect(t.x, top, 1, t.h);
		const cx = t.x + t.w / 2;
		for (let r = 0; r <= t.s; r++) {
			const half = (t.w / 2 + 1) * (1 - r / t.s);
			g.fillStyle = castleColor;
			g.fillRect(Math.floor(cx - half), top - 1 - r, Math.max(1, Math.ceil(half * 2)), 1);
		}
		// ventanitas cálidas
		for (let k = 0; k < 3; k++) if (rnd() > .45) px(t.x + 2 + Math.floor(rnd() * (t.w - 3)), top + 8 + k * 11, "#ff7a3a");
	});

	/* colina media (tapa la base del castillo) */
	hill(106, [[7, .04, 1], [4, .1, 2.2], [2, .27, .5]], "#463139", "#6a4a50",
		x => -12 * Math.exp(-(((x - 212) / 34) ** 2)));

	/* colina cercana (más alta en los bordes) */
	hill(124, [[8, .05, 0], [3, .14, 1]], "#22161d", "#3d2a32",
		x => -26 * Math.pow(Math.abs(x - W / 2) / (W / 2), 2.4));

	/* río de lava */
	const yStart = 98;
	const cxAt = y => {
		const t = (y - yStart) / (H - yStart);
		return 128 + Math.sin(t * 7.2) * 20 * Math.min(1, t * 2.4);
	};
	for (let y = yStart; y < H; y++) {
		const t = (y - yStart) / (H - yStart);
		const c = cxAt(y);
		const half = 1.5 + t * 15 + Math.sin(y * .5) * .7;
		for (let x = Math.floor(c - half - 6); x <= c + half + 6; x++) {
			const d = Math.abs(x - c) / half;
			if (d > 1.25) {
				const glow = 1 - (d - 1.25) / ((6 / half) + .01);
				if (glow > BAYER[y & 3][x & 3] + .25) px(x, y, "#7a2a22");
				continue;
			}
			let col = d > 1 ? "#2a0c10" : d > .8 ? "#8f1a0a" : d > .5 ? "#e5420e" : d > .22 ? "#ff8a1c" : "#ffc43a";
			if (d <= 1 && rnd() < .05) col = "#ffe27a";
			px(x, y, col);
		}
	}
	// charcos de lava abajo
	ellipse(12, 140, 22, 4, "#2a0c10"); ellipse(12, 140, 20, 3, "#8f1a0a"); ellipse(13, 140, 15, 2, "#e5420e"); ellipse(14, 140, 8, 1, "#ff9a22");
	ellipse(245, 141, 18, 3, "#2a0c10"); ellipse(245, 141, 16, 2, "#8f1a0a"); ellipse(245, 141, 11, 1.4, "#e5420e");

	/* árboles secos */
	function line(x0, y0, x1, y1, c) {
		x0 = Math.round(x0); y0 = Math.round(y0); x1 = Math.round(x1); y1 = Math.round(y1);
		const dx = Math.abs(x1 - x0), dy = Math.abs(y1 - y0);
		const sx = x0 < x1 ? 1 : -1, sy = y0 < y1 ? 1 : -1;
		let err = dx - dy;
		for (;;) {
			px(x0, y0, c);
			if (x0 === x1 && y0 === y1) break;
			const e2 = 2 * err;
			if (e2 > -dy) { err -= dy; x0 += sx; }
			if (e2 < dx) { err += dx; y0 += sy; }
		}
	}
	function branch(x, y, a, len, depth) {
		const ex = x + Math.cos(a) * len, ey = y - Math.sin(a) * len;
		line(x, y, ex, ey, "#0d070c");
		if (depth >= 3) line(x + 1, y, ex + 1, ey, "#0d070c");
		if (depth <= 0) return;
		branch(ex, ey, a + .5 + rnd() * .5, len * .72, depth - 1);
		branch(ex, ey, a - .5 - rnd() * .5, len * .7, depth - 1);
		if (rnd() > .6) branch(ex, ey, a + (rnd() - .5) * .4, len * .6, depth - 1);
	}
	branch(24, 120, Math.PI / 2 + .1, 17, 4);
	branch(246, 118, Math.PI / 2 - .15, 15, 4);
	branch(64, 113, Math.PI / 2, 9, 3);
	branch(208, 124, Math.PI / 2 + .2, 8, 3);

	/* viñeta tramada */
	for (let y = 0; y < H; y++)
		for (let x = 0; x < W; x++) {
			const d = Math.hypot((x - W / 2) / (W / 2), (y - H / 2) / (H / 2));
			if (d > .75 && (d - .75) * 1.1 > BAYER[y & 3][x & 3]) px(x, y, "#0a0306");
		}
})();

/* ---------- textura de piedra de la tarjeta ---------- */
(function () {
	const tex = document.getElementById("tex");
	const card = tex.parentElement;
	const S = 4;

	function hash(a, b) {
		let t = (Math.imul(a, 374761393) + Math.imul(b, 668265263)) >>> 0;
		t = Math.imul(t ^ (t >>> 13), 1274126177) >>> 0;
		return ((t ^ (t >>> 16)) >>> 0) / 4294967296;
	}

	function paint() {
		const w = Math.max(20, Math.ceil(card.offsetWidth / S));
		const h = Math.max(20, Math.ceil(card.offsetHeight / S));
		tex.width = w; tex.height = h;
		const g = tex.getContext("2d");
		const rnd = mulberry32(21);
		const px = (x, y, c) => { g.fillStyle = c; g.fillRect(x, y, 1, 1); };

		const stone = ["#6b6b72", "#7c7c83", "#5a5a61", "#8d8d94", "#64646b"];
		const brick = ["#243040", "#2a3647", "#202a39", "#27323f"];

		for (let y = 0; y < h; y++)
			for (let x = 0; x < w; x++) {
				const edge = Math.min(x, y, w - 1 - x, h - 1 - y);
				if (edge < 2) {
					px(x, y, stone[Math.floor(rnd() * stone.length)]);
				} else if (edge === 2) {
					px(x, y, "#15171d");
				} else {
					const ly = y - 3;
					const row = Math.floor(ly / 5);
					const lx = x - 3 + (row % 2 ? 4 : 0);
					if (ly % 5 === 4 || lx % 8 === 7) { px(x, y, "#0b0e14"); continue; }
					const id = hash(row, Math.floor(lx / 8));
					let c = id < .07 ? "#10131a" : brick[Math.floor(id * 97) % brick.length];
					if (ly % 5 === 0 && id >= .07) c = "#33425a";
					if (rnd() < .04) c = "#1a2230";
					px(x, y, c);
				}
			}

		// grietas
		for (let k = 0; k < 7; k++) {
			let x = Math.floor(rnd() * w), y = Math.floor(rnd() * h);
			const len = 5 + Math.floor(rnd() * 10);
			for (let i = 0; i < len; i++) {
				px(x, y, "#0a0c10");
				x += Math.floor(rnd() * 3) - 1; y += Math.floor(rnd() * 3) - 1;
				x = Math.max(0, Math.min(w - 1, x)); y = Math.max(0, Math.min(h - 1, y));
			}
		}
		// esquinas recortadas
		[[0,0],[w-1,0],[0,h-1],[w-1,h-1]].forEach(([cx, cy]) => g.clearRect(cx, cy, 1, 1));
	}

	paint();
	addEventListener("resize", paint);
	if (document.fonts && document.fonts.ready) document.fonts.ready.then(paint);
})();
